"""Returns a flattened version of lst.

    >>> flatten([1, 2, 3])     # normal list
    [1, 2, 3]
    >>> x = [1, [2, 3], 4]      # deep list
    >>> flatten(x)
    [1, 2, 3, 4]
    >>> x = [[1, [1, 1]], 1, [1, 1]] # deep list
    >>> flatten(x)
    [1, 1, 1, 1, 1, 1]
    """
def flatten(lst: Any) -> object {
    new_list = [];
    for i in lst {
        if (`type(i) == `list) {
            new_list += flatten(i);
        } else {
            new_list.append(i);
        }
    }
    return new_list;
}

